hl.on("hyprland.start", function()
    -- Propagate env (incl. DBUS) to the already-running user bus (portable: systemd + OpenRC/elogind)
    hl.exec_cmd("bash ~/.config/hypr/scripts/dbus_env.sh")
    -- OpenRC User Audio Stack (PipeWire, WirePlumber, Pulse)
    hl.exec_cmd([[bash -c 'pgrep -u "$UID" -x pipewire >/dev/null || pipewire' &]])
    hl.exec_cmd([[bash -c 'sleep 0.2; pgrep -u "$UID" -x wireplumber >/dev/null || wireplumber' &]])
    hl.exec_cmd([[bash -c 'sleep 0.3; pgrep -u "$UID" -x pipewire-pulse >/dev/null || pipewire-pulse' &]])
    hl.exec_cmd([[hyprpolkitagent &]])
    hl.exec_cmd([[awww-daemon &]])
    hl.exec_cmd([[hypridle &]])
    hl.exec_cmd([[bash -c 'quickshell -p $HOME/.config/hypr/scripts/quickshell/Shell.qml' &]])
    hl.exec_cmd([[bash ~/.config/hypr/scripts/quickshell/focustime/launch_daemon.sh &]])
    hl.exec_cmd([[bash ~/.config/hypr/scripts/init.sh &]])
    hl.exec_cmd([[bash ~/.config/hypr/scripts/settings_watcher.sh &]])
    hl.exec_cmd([[playerctld &]])
    hl.exec_cmd([[swayosd-server --top-margin 0.9 --style "$HOME/.config/swayosd/style.css" &]])
    hl.exec_cmd([[wl-paste --type text --watch cliphist store &]])
    hl.exec_cmd([[wl-paste --type image --watch cliphist store &]])
    hl.exec_cmd([[bash ~/.config/hypr/scripts/volume_listener.sh &]])
    hl.exec_cmd([[bash ~/.config/hypr/scripts/update_notifier.sh &]])
    hl.exec_cmd([[bash ~/.config/hypr/scripts/brightness.sh restore &]])
    hl.exec_cmd([[bash -c 'pkill -f infinite_desktop_core.py; python3 $HOME/.config/hypr/scripts/infinite_desktop/infinite_desktop_core.py 1.6' &]])
end)
